SELECT customer_contact_pregress_details.customer_progress_type_id as typeId, customer_contact_progress_types.name as typeName, customer_contact_pregress_details.`id` as id, customer_contact_pregress_details.`name` as name FROM `customer_contact_pregress_details` LEFT JOIN customer_contact_progress_types ON customer_contact_pregress_details.customer_progress_type_id = customer_contact_progress_types.id AND customer_contact_progress_types.is_active = 1 WHERE customer_contact_pregress_details.`is_active` = 1
